import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Ho.css";

const images = Array.from({ length: 18 }, (_, i) => `/images/a${i + 1}.gif`);

const CATEGORIES = {
  ALL: 'all',
  RED: 'red',
  BLUE: 'blue',
  GREEN: 'green',
  YELLOW: 'yellow',
  WHITE: 'white',
  BLACK: 'black',
  OTHER: 'other'
};

function Home() {
  const [selectedImages, setSelectedImages] = useState([]);
  const [uploadedImages, setUploadedImages] = useState([]);
  const [activeCategory, setActiveCategory] = useState(CATEGORIES.ALL);
  const fileInputRef = useRef();
  const navigate = useNavigate();

  // Load uploaded images from localStorage on component mount
  useEffect(() => {
    const savedImages = localStorage.getItem('uploadedImages');
    if (savedImages) {
      setUploadedImages(JSON.parse(savedImages));
    }
  }, []);

  // Save uploaded images to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('uploadedImages', JSON.stringify(uploadedImages));
  }, [uploadedImages]);

  const getDominantColor = async (imageUrl) => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "Anonymous";
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
        const colorMap = new Map();

        // Sample colors with higher precision
        for (let i = 0; i < imageData.length; i += 4) {
          const r = imageData[i];
          const g = imageData[i + 1];
          const b = imageData[i + 2];
          const a = imageData[i + 3];

          // Skip transparent pixels
          if (a < 128) continue;

          // Quantize colors to reduce noise while maintaining color richness
          const quantizedR = Math.round(r / 16) * 16;
          const quantizedG = Math.round(g / 16) * 16;
          const quantizedB = Math.round(b / 16) * 16;

          const colorKey = `${quantizedR},${quantizedG},${quantizedB}`;
          colorMap.set(colorKey, (colorMap.get(colorKey) || 0) + 1);
        }

        // Get the most frequent color
        const sortedColors = Array.from(colorMap.entries())
          .sort((a, b) => b[1] - a[1])
          .slice(0, 1)[0][0]
          .split(',')
          .map(Number);

        const [r, g, b] = sortedColors;
        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const delta = max - min;
        const saturation = delta / max;

        let category;
        if (saturation < 0.15) {
          // Low saturation - grayscale
          if (max < 50) category = CATEGORIES.BLACK;
          else if (max > 200) category = CATEGORIES.WHITE;
          else category = CATEGORIES.OTHER;
        } else {
          // High saturation - determine dominant color
          const rRatio = r / max;
          const gRatio = g / max;
          const bRatio = b / max;

          if (rRatio > 0.8 && gRatio < 0.6 && bRatio < 0.6) {
            category = CATEGORIES.RED;
          } else if (gRatio > 0.8 && rRatio < 0.6 && bRatio < 0.6) {
            category = CATEGORIES.GREEN;
          } else if (bRatio > 0.8 && rRatio < 0.6 && gRatio < 0.6) {
            category = CATEGORIES.BLUE;
          } else if (rRatio > 0.7 && gRatio > 0.7 && bRatio < 0.4) {
            category = CATEGORIES.YELLOW;
          } else {
            category = CATEGORIES.OTHER;
          }
        }

        resolve(category);
      };
      img.src = imageUrl;
    });
  };

  const getColorPalette = (imageData, numColors = 5) => {
    const data = imageData.data;
    const colorMap = new Map();

    // Sample colors with higher precision
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const a = data[i + 3];

      // Skip transparent pixels
      if (a < 128) continue;

      // Quantize colors to reduce noise while maintaining color richness
      const quantizedR = Math.round(r / 16) * 16;
      const quantizedG = Math.round(g / 16) * 16;
      const quantizedB = Math.round(b / 16) * 16;

      const colorKey = `${quantizedR},${quantizedG},${quantizedB}`;
      colorMap.set(colorKey, (colorMap.get(colorKey) || 0) + 1);
    }

    // Sort colors by frequency and get the top N colors
    const sortedColors = Array.from(colorMap.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, numColors)
      .map(([colorKey]) => colorKey.split(',').map(Number));

    return sortedColors;
  };

  const handleFileUpload = async (event) => {
    const files = Array.from(event.target.files);

    for (const file of files) {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();

        reader.onload = async (e) => {
          const imageUrl = e.target.result;
          const category = await getDominantColor(imageUrl);
          setUploadedImages(prev => [...prev, {
            url: imageUrl,
            category,
            timestamp: new Date().toISOString()
          }]);
        };

        reader.readAsDataURL(file);
      }
    }
  };

  const toggleImage = (img) => {
    setSelectedImages((prev) => {
      if (prev.includes(img)) {
        return prev.filter((i) => i !== img);
      } else if (prev.length < 3) {
        return [...prev, img];
      }
      return prev;
    });
  };

  const generateImage = async () => {
    if (selectedImages.length === 0) return;

    const canvas = document.createElement('canvas');
    canvas.width = 1080;
    canvas.height = 1080;
    const ctx = canvas.getContext('2d');

    // Step 1: Stack images with multiply blend mode
    ctx.globalCompositeOperation = 'multiply';
    for (const imgUrl of selectedImages) {
      const img = await loadImage(imgUrl);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    }

    // Step 2: Get color palette
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const colorPalette = getColorPalette(imageData, 5);

    // Step 3: Create binary masks for each color
    const masks = await Promise.all(colorPalette.map(async (color) => {
      const maskCanvas = document.createElement('canvas');
      maskCanvas.width = canvas.width;
      maskCanvas.height = canvas.height;
      const maskCtx = maskCanvas.getContext('2d');

      for (let i = 0; i < imageData.data.length; i += 4) {
        const r = imageData.data[i];
        const g = imageData.data[i + 1];
        const b = imageData.data[i + 2];

        // Improved color matching with weighted RGB differences
        const rDiff = Math.abs(r - color[0]);
        const gDiff = Math.abs(g - color[1]);
        const bDiff = Math.abs(b - color[2]);
        const totalDiff = (rDiff + gDiff + bDiff) / 3;

        const isClose = totalDiff < 40; // Increased threshold for better color matching

        maskCtx.fillStyle = isClose ? 'white' : 'black';
        maskCtx.fillRect((i/4) % canvas.width, Math.floor((i/4) / canvas.width), 1, 1);
      }

      return maskCanvas;
    }));

    // Step 4 & 5: Process each mask and place shapes
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (const mask of masks) {
      const contours = await findContours(mask);

      for (const contour of contours) {
        // Random position and size with more variation
        const scale = 0.3 + Math.random() * 0.7; // More size variation
        const angle = Math.random() * Math.PI * 2;
        const x = canvas.width/2 + (Math.random() - 0.5) * 300; // Increased spread
        const y = canvas.height/2 + (Math.random() - 0.5) * 300;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(angle);
        ctx.scale(scale, scale);

        // Draw the shape with original color
        ctx.beginPath();
        ctx.moveTo(contour[0].x, contour[0].y);
        for (let i = 1; i < contour.length; i++) {
          ctx.lineTo(contour[i].x, contour[i].y);
        }
        ctx.closePath();
        ctx.fillStyle = `rgb(${colorPalette[masks.indexOf(mask)].join(',')})`;
        ctx.fill();
        ctx.restore();
      }
    }

    // Save the result
    localStorage.setItem("generatedImage", canvas.toDataURL());
    navigate("/generate");
  };

  const loadImage = (src) => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "Anonymous";
      img.onload = () => resolve(img);
      img.src = src;
    });
  };

  const findContours = async (canvas) => {
    const ctx = canvas.getContext('2d');
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const contours = [];
    let currentContour = null;

    // Simple edge detection and contour tracing
    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        const i = (y * canvas.width + x) * 4;
        if (data[i] > 128) { // White pixel
          if (!currentContour) {
            currentContour = [{x, y}];
            contours.push(currentContour);
          } else {
            currentContour.push({x, y});
          }
        } else {
          currentContour = null;
        }
      }
    }

    // Filter out tiny contours
    return contours.filter(contour => contour.length > 10);
  };

  const removeUploadedImage = (index) => {
    setUploadedImages(prev => prev.filter((_, i) => i !== index));
  };

  const filteredUploadedImages = activeCategory === CATEGORIES.ALL
    ? uploadedImages
    : uploadedImages.filter(img => img.category === activeCategory);

  return (
    <div className="ho-container">
      <h1 className="ho-title">Select Images</h1>

      <div className="ho-selection-info">
        Selected: {selectedImages.length}/3 images
      </div>

      <div className="ho-upload-section">
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileUpload}
          accept="image/*"
          multiple
          style={{ display: 'none' }}
        />
        <button
          className="ho-upload-button"
          onClick={() => fileInputRef.current.click()}
        >
          Upload Images
        </button>
      </div>

      {uploadedImages.length > 0 && (
        <div className="ho-category-filters">
          <button
            className={`ho-category-button ho-category-all ${activeCategory === CATEGORIES.ALL ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.ALL)}
          >
            All
          </button>
          <button
            className={`ho-category-button ho-category-red ${activeCategory === CATEGORIES.RED ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.RED)}
          >
            Red
          </button>
          <button
            className={`ho-category-button ho-category-blue ${activeCategory === CATEGORIES.BLUE ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.BLUE)}
          >
            Blue
          </button>
          <button
            className={`ho-category-button ho-category-green ${activeCategory === CATEGORIES.GREEN ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.GREEN)}
          >
            Green
          </button>
          <button
            className={`ho-category-button ho-category-yellow ${activeCategory === CATEGORIES.YELLOW ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.YELLOW)}
          >
            Yellow
          </button>
          <button
            className={`ho-category-button ho-category-white ${activeCategory === CATEGORIES.WHITE ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.WHITE)}
          >
            White
          </button>
          <button
            className={`ho-category-button ho-category-black ${activeCategory === CATEGORIES.BLACK ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.BLACK)}
          >
            Black
          </button>
          <button
            className={`ho-category-button ho-category-other ${activeCategory === CATEGORIES.OTHER ? 'active' : ''}`}
            onClick={() => setActiveCategory(CATEGORIES.OTHER)}
          >
            Other
          </button>
        </div>
      )}

      <div className="ho-grid">
        {/* Display existing images */}
        {images.map((img, i) => {
          const selectedIndex = selectedImages.indexOf(img);
          return (
            <div key={`existing-${i}`} className="ho-image-container">
              <img
                src={img}
                alt={`tile-${i}`}
                onClick={() => toggleImage(img)}
                className={`ho-image ${selectedIndex !== -1 ? 'selected' : ''}`}
              />
              {selectedIndex !== -1 && (
                <div className="ho-image-number">
                  {selectedIndex + 1}
                </div>
              )}
            </div>
          );
        })}

        {/* Display uploaded images */}
        {filteredUploadedImages.map((img, i) => {
          const selectedIndex = selectedImages.indexOf(img.url);
          return (
            <div key={`uploaded-${i}`} className="ho-image-container">
              <img
                src={img.url}
                alt={`uploaded-${i}`}
                onClick={() => toggleImage(img.url)}
                className={`ho-image ${selectedIndex !== -1 ? 'selected' : ''}`}
              />
              {selectedIndex !== -1 && (
                <div className="ho-image-number">
                  {selectedIndex + 1}
                </div>
              )}
              <button
                className="ho-remove-button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeUploadedImage(i);
                }}
              >
                ×
              </button>
            </div>
          );
        })}
      </div>

      <button
        className="ho-generate-button"
        onClick={generateImage}
        disabled={selectedImages.length === 0}
      >
        Generate
      </button>
    </div>
  );
}

export default Home;
